import numpy as np, pandas as pd, os
from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
xs={}
for s in U:
 try: d=get_index_daily_data(s,days=6000)
 except: 
  try: d=get_stock_daily_data(s,days=6000)
  except: d=None
 if d is not None and len(d): xs[s]=d.set_index(pd.to_datetime(d.date)).close.astype(float).sort_index()
p=pd.DataFrame(xs).sort_index().ffill(); r=p.pct_change()
csdisp=r.rolling(5).std(axis=1).mean(axis=1); threshold=csdisp.rolling(60,min_periods=40).median(); active=(csdisp>threshold).astype(float)
vol=r.rolling(20).std(); f=-(r.rolling(5).sum().shift(1))/vol.shift(1)*active.shift(1)
print('instruments',len(xs),list(xs),'rows',len(p))
for h in [5,10,20,40]:
 vals=[]; dates=[]; ns=[]; fr=p.pct_change(h).shift(-h)
 for dt in f.index:
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
   vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); dates.append(dt); ns.append(len(z))
 q=pd.Series(vals,index=dates).dropna(); print('H',h,'dates',len(q),'avgN',np.mean(ns),'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1),'hit',(q>0).mean())
 if h==10:
  for a,b in [('2020','2024'),('2025','2029'),('2030','2035')]:
   z=q.loc[a:b]; print('regime',a,len(z),z.mean(),z.mean()/z.std(ddof=1))
print('turnover',f.rank(axis=1,pct=True).diff().abs().mean().mean())

